@ Some portions generated by Claude Code (Opus 5).

@ zx_el2_entry.S -- Cortex-R52 -- the ZoneX EL2 reset and entry path.
@
@ DESCRIPTION
@
@   Where ZoneX starts.  Establishes the Hyp-mode stack, installs HVBAR,
@   puts EL2 in a known configuration, zeroes .bss and hands over to
@   zx_el2_main -- staying at EL2 rather than dropping to EL1, which is what
@   distinguishes this from the ThreadX Cortex-R52 port's entry.S that it is
@   modelled on.  In ZoneX, EL2 is the program and EL1 is a payload it
@   launches; see zx_trap_handler.S for that launch.
@
@ THE ORDER BELOW IS LOAD-BEARING
@
@   1. HSCTLR.TE is cleared FIRST, before anything can fault.  TE set means
@      EL2 exceptions are entered in T32 state, so an A32 vector table never
@      runs and every fault presents as a silent hang.  It resets SET on the
@      S32Z280 -- SCTLR reads 0x70C50838 there, bit 30 high -- and clear on
@      the Armv8-R AEM FVP, which is exactly the shape of difference that
@      makes a green model run worthless as evidence about the part.  Its
@      pre-clear value is kept and reported.
@
@   2. SCTLR.M is cleared, leaving the EL1 MPU DISABLED.  That is deliberate
@      for the first stage-2 image: with stage 1 off, the payload runs on the
@      EL1 background map and the only thing under test is stage 2.  One
@      variable at a time; stage 1 comes back when a real ThreadX guest does.
@
@   3. The Hyp stack exists before anything is pushed at EL2.
@
@   4. HVBAR is installed before HCR is touched, so that if anything after it
@      faults, the fault is reported instead of vanishing.
@
@   5. HCR.VM stays CLEAR here.  Turning stage 2 on is the whole subject of
@      this repository and it happens in C, in zx_stage2_enable, after the
@      regions exist -- enabling HCR.VM with no region covering the payload's
@      code faults at the ERET target and presents as "the guest never
@      started", which looks nothing like a memory-protection problem.
@
@   HMAIR0/HMAIR1 are programmed in C rather than here, in zx_mair_program,
@   called from zx_el2_main before any region is written.  The ordering
@   requirement is only that attributes exist before HSCTLR.M is set, and C is
@   where the byte values are readable next to the AttrIndx names they belong
@   to.
@
@ NOTE ON SYNTAX
@
@   GNU assembler syntax, per CONTRIBUTING.md.  '@' is the AArch32 comment
@   character; this file is assembled through the C preprocessor (it is
@   .S, not .s), so it shares every constant with the C sources through
@   zx_port.h and spells none of them itself.

#include "zx_port.h"

    .syntax unified

@ No .arch directive.  GNU as accepts "armv8-r" and LLVM's integrated
@ assembler accepts no spelling of it at all, failing with "Unknown Arch".
@ The architecture is already selected by -mcpu=cortex-r52 on the command
@ line, which both toolchain files pass, so the directive only restated it.

/**************************************************************************/
/*  _start -- reset entry, at EL2 (Hyp mode).                             */
/*                                                                        */
/*  Whether the core arrives here in A32 or T32 state is a BOARD fact, not */
/*  an architectural one, so it is a build option rather than a run-time   */
/*  test -- there is nothing to test with before the first instruction.    */
/*                                                                        */
/*  ZX_RESET_IN_THUMB is defined for the S32Z280, where the RTU boot        */
/*  instruction NXP plants is a T32 branch and CPSR reads 0x1FA out of      */
/*  reset.  An A32 entry there executes the first halfword of its own      */
/*  instruction as Thumb and goes anywhere.  The Armv8-R AEM FVP enters in */
/*  A32 state and needs no trampoline.                                    */
/*                                                                        */
/*  .text.boot is linked FIRST on the S32Z280, because the core's reset    */
/*  address is the start of its code SRAM: whatever lands there is what     */
/*  executes, and it has to be _start.                                     */
/**************************************************************************/

#ifdef ZX_RESET_IN_THUMB

    .section .text.boot, "ax"
    .thumb
    .balign 2
    .global _start
    .type   _start, %function
_start:

    @ CPSR as the very first instruction, before the state switch.
    @
    @ AND IT STILL CANNOT SEE THE T BIT.  Measured: this instruction reads
    @ 0x000001DA on BOTH ZoneX targets, while the S32Z280 demonstrably
    @ begins execution in T32 state -- the instruction doing the reading is
    @ a T32 encoding and executes correctly -- and the Armv8-R AEM FVP
    @ begins in A32.  Two different execution states, one reading.  So
    @ MRS Rd, CPSR does not report PSTATE.T, and an image cannot learn its
    @ own execution state from it.  A DEBUGGER can: gdb shows T set on the
    @ board, which is where the 0x1FA reading recorded during the
    @ Cortex-R52 port work came from.
    @
    @ The snapshot is taken here anyway, because everything else in CPSR --
    @ the mode field above all -- is exactly what wants recording, and this
    @ is the earliest instruction there is.  r6 carries it into A32; nothing
    @ between here and the store touches it.

    mrs     r6, cpsr

    @ Leave Thumb.  zx_el2_start_a32 is an A32 symbol, so the linker clears
    @ bit 0 of its address and BX switches state.

    ldr     r0, =zx_el2_start_a32
    bx      r0
    .size   _start, . - _start

#endif

    .section .text.boot, "ax"
    .arm
    .balign 4

#ifndef ZX_RESET_IN_THUMB
    .global _start
    .type   _start, %function
_start:
#endif

    .global zx_el2_start_a32
    .type   zx_el2_start_a32, %function
zx_el2_start_a32:

    @ ------------------------------------------------------------------
    @ 1. HSCTLR.TE, before anything can fault.  r4 keeps the reset value
    @    so that the identity block can report what the part reset to.
    @
    @    C and I go with it, leaving EL2's caches OFF.  That is the simplest
    @    memory configuration a bring-up failure can be reproduced in, and
    @    it is what the Cortex-R52 port defaults to for the same reason.  It
    @    also removes one variable from the stage-2 measurements this image
    @    exists to make.  Caches are a step-5 concern, where the timing
    @    claims are, and they will need HMAIR and the region attributes to
    @    be right first -- which is what this image establishes.
    @ ------------------------------------------------------------------

    mrc     p15, 4, r4, c1, c0, 0           @ HSCTLR, as reset
    ldr     r0, =(ZX_HSCTLR_TE | ZX_HSCTLR_C | ZX_HSCTLR_I)
    bic     r0, r4, r0
    mcr     p15, 4, r0, c1, c0, 0
    isb

    @ ------------------------------------------------------------------
    @ 2. SCTLR: clear TE for the same reason, and clear M so that the EL1
    @    MPU is OFF.  Caches stay off too -- see the note below.
    @ ------------------------------------------------------------------

    mrc     p15, 0, r5, c1, c0, 0           @ SCTLR, as reset
    ldr     r0, =(ZX_SCTLR_TE | ZX_SCTLR_M | ZX_SCTLR_C | ZX_SCTLR_I)
    bic     r0, r5, r0
    mcr     p15, 0, r0, c1, c0, 0
    isb

#ifndef ZX_RESET_IN_THUMB

    @ CPSR as reset, which is what says which mode and state the core
    @ actually arrived in rather than which one this file assumed.  On a
    @ target that resets in T32 this was already taken in the trampoline
    @ above, BEFORE the state switch -- see the note there.

    mrs     r6, cpsr

#endif

    @ ------------------------------------------------------------------
    @ 3. Hyp stack.
    @ ------------------------------------------------------------------

    ldr     sp, =__zx_hyp_stack_top

    @ ------------------------------------------------------------------
    @ 4. EL2 vector table.
    @ ------------------------------------------------------------------

    ldr     r0, =zx_el2_vectors
    mcr     p15, 4, r0, c12, c0, 0          @ HVBAR
    isb

    @ ------------------------------------------------------------------
    @ 5. HCR, into a known state.
    @
    @    Every bit here is cleared, including the ones that reset clear,
    @    because "it resets to what we want" is a claim about a part and
    @    ZoneX runs on more than one:
    @
    @      VM   stage 2 stays off until zx_stage2_enable turns it on.
    @      TGE  set would route EL1's own exceptions differently and stop
    @           the guest's vectors being used at all -- not what Phase 0
    @           wants, since a guest must keep its own exception handling.
    @      AMO  a stage-2 fault is taken to EL2 because it is a fault in
    @      IMO  the EL2 translation regime, NOT because AMO routes it, so
    @      FMO  EL1's own aborts and interrupts are left with EL1.
    @      HCD  clear keeps HVC available, which is the hypercall seam.
    @ ------------------------------------------------------------------

    mrc     p15, 4, r0, c1, c1, 0           @ HCR
    ldr     r1, =(ZX_HCR_TGE | ZX_HCR_AMO | ZX_HCR_IMO | ZX_HCR_FMO | \
                  ZX_HCR_VM | ZX_HCR_HCD | ZX_HCR_DC)
    bic     r0, r0, r1
    mcr     p15, 4, r0, c1, c1, 0
    isb

    @ ------------------------------------------------------------------
    @ 5b. GICv3 system-register interface.
    @
    @     This is not GIC bring-up -- Phase 0 configures no interrupts at
    @     all.  It is here because ICC_HSRE.SRE is what makes every other
    @     ICC_* and ICH_* system register EXIST: reading ICH_VTR with SRE
    @     clear takes an Undefined Instruction exception at EL2.  That was
    @     measured on the Armv8-R AEM FVP rather than read anywhere, and the
    @     identity block reads ICH_VTR to report the List Register count.
    @ ------------------------------------------------------------------

    mrc     p15, 4, r0, c12, c9, 5          @ ICC_HSRE
    orr     r0, r0, #(ZX_ICC_HSRE_SRE | ZX_ICC_HSRE_ENABLE)
    mcr     p15, 4, r0, c12, c9, 5
    isb

    @ ------------------------------------------------------------------
    @ 5c. HPRENR, and how wide it really is.
    @
    @     The TRM contradicts itself about this register: its prose says
    @     HPRENR covers "regions 0 to 15" while its own bit tables give
    @     [19:0] for a 20-region implementation and [23:0] for a 24-region
    @     one.  Two things are measured here and both are recorded:
    @
    @       r7  the reset value.
    @       r8  what sticks when all ones are written -- which says which
    @           bits are implemented AT ALL, as opposed to which bits WORK.
    @
    @     The read-back is the weaker of the two tests and is taken anyway,
    @     because the failure worth catching is a register that accepts a
    @     bit above 15 and IGNORES it: that passes a read-back test and
    @     fails a functional one, and only having both distinguishes it
    @     from a register that is genuinely narrow.  The functional test --
    @     disable a region above 15 and prove the memory it covered stops
    @     being reachable from EL1 -- is in the probe image.
    @
    @     Safe here and nowhere later: HSCTLR.M resets CLEAR on both ZoneX
    @     targets, so no region is being consulted and enabling twenty of
    @     them with UNKNOWN bases cannot produce the overlapping-region
    @     abort that PMSAv8-R's lack of region priority makes possible.
    @     HPRENR is put back to zero immediately.
    @ ------------------------------------------------------------------

    mrc     p15, 4, r7, c6, c1, 1           @ HPRENR, as reset
    mvn     r0, #0
    mcr     p15, 4, r0, c6, c1, 1
    isb
    mrc     p15, 4, r8, c6, c1, 1           @ how much of all-ones stuck
    mov     r0, #0
    mcr     p15, 4, r0, c6, c1, 1
    isb

    @ ------------------------------------------------------------------
    @ 6. Zero .bss.  Before this, no C object may be read -- which is why
    @    the four snapshots above ride in registers rather than being
    @    stored as they are taken.
    @ ------------------------------------------------------------------

    ldr     r0, =__zx_bss_start
    ldr     r1, =__zx_bss_end
    mov     r2, #0
zx_el2_bss_zero_loop:
    cmp     r0, r1
    bhs     zx_el2_bss_zero_done
    str     r2, [r0], #4
    b       zx_el2_bss_zero_loop
zx_el2_bss_zero_done:

    @ ------------------------------------------------------------------
    @ 7. Publish the snapshots and hand over.
    @ ------------------------------------------------------------------

    ldr     r0, =zx_reset_hsctlr
    str     r4, [r0]
    ldr     r0, =zx_reset_sctlr
    str     r5, [r0]
    ldr     r0, =zx_reset_cpsr
    str     r6, [r0]
    ldr     r0, =zx_reset_hprenr
    str     r7, [r0]
    ldr     r0, =zx_hprenr_implemented_bits
    str     r8, [r0]

    dsb
    isb

    bl      zx_el2_main

    @ zx_el2_main is ZX_NORETURN.  If it returns anyway, the image is not in
    @ a state anybody should reason about, so it stops here rather than
    @ running off the end of .text into whatever follows.

    .global zx_el2_start_hang
zx_el2_start_hang:
    b       zx_el2_start_hang
    .size   zx_el2_start_a32, . - zx_el2_start_a32
